export interface BucketConfig {
  capacity: number;
  refillPerSecond: number;
}

interface Bucket {
  tokens: number;
  lastRefillMs: number;
}

export type Decision =
  | { allowed: true; remaining: number }
  | { allowed: false; retryAfterSeconds: number };

export class MerchantRateLimiter {
  private readonly buckets = new Map<string, Bucket>();

  constructor(
    private readonly config: BucketConfig,
    private readonly now: () => number = Date.now,
  ) {}

  tryConsume(merchantId: string, cost = 1): Decision {
    const nowMs = this.now();
    let bucket = this.buckets.get(merchantId);
    if (!bucket) {
      bucket = { tokens: this.config.capacity, lastRefillMs: nowMs };
      this.buckets.set(merchantId, bucket);
    }

    const elapsedSec = (nowMs - bucket.lastRefillMs) / 1000;
    bucket.tokens = bucket.tokens + elapsedSec * this.config.refillPerSecond;
    bucket.lastRefillMs = nowMs;

    if (bucket.tokens >= cost) {
      bucket.tokens -= cost;
      return { allowed: true, remaining: Math.floor(bucket.tokens) };
    }

    const deficit = cost - bucket.tokens;
    return {
      allowed: false,
      retryAfterSeconds: Math.ceil(deficit / this.config.refillPerSecond),
    };
  }

  evictIdle(maxIdleMs: number): number {
    const cutoff = this.now() - maxIdleMs;
    let removed = 0;
    for (const [id, b] of this.buckets) {
      if (b.lastRefillMs < cutoff) {
        this.buckets.delete(id);
        removed++;
      }
    }
    return removed;
  }
}

import { MerchantRateLimiter } from "./merchantRateLimiter";

export interface ChargeRequest {
  merchantId: string;
  idempotencyKey: string;
  amountMinor: number;
  currency: string;
  lineItems: number;
}

export interface Processor {
  charge(req: ChargeRequest): Promise<{ chargeId: string }>;
}

type HttpResult = { status: number; headers?: Record<string, string>; body: unknown };

const limiter = new MerchantRateLimiter({ capacity: 50, refillPerSecond: 10 });

setInterval(() => limiter.evictIdle(10 * 60_000), 60_000).unref();

export async function createCharge(
  req: ChargeRequest,
  processor: Processor,
): Promise<HttpResult> {
  if (!req.idempotencyKey) {
    return { status: 400, body: { error: "idempotency_key_required" } };
  }

  const cost = req.lineItems > 20 ? 2 : 1;
  const decision = limiter.tryConsume(req.merchantId, cost);

  if (!decision.allowed) {
    return {
      status: 429,
      headers: { "Retry-After": String(decision.retryAfterSeconds) },
      body: { error: "rate_limited" },
    };
  }

  try {
    const { chargeId } = await processor.charge(req);
    return {
      status: 201,
      headers: { "X-RateLimit-Remaining": String(decision.remaining) },
      body: { chargeId },
    };
  } catch {
    return { status: 502, body: { error: "processor_error" } };
  }
}
